package com.bookstore.bike.controller;
import com.bookstore.bike.entity.*; import com.bookstore.bike.repo.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/bikes") public class BikeController {final BikeRepository bikes;final UserRepository users; BikeController(BikeRepository b,UserRepository u){bikes=b;users=u;} public record BikeRequest(@NotBlank String name,String brand,String model,String registrationNumber,String description,String city,String pickupLocation,Enums.BikeType type,Enums.FuelType fuelType,@NotNull @Positive BigDecimal pricePerHour,@NotNull @Positive BigDecimal pricePerDay,BigDecimal depositAmount,String imageUrl){}
 @GetMapping public List<Bike> list(@RequestParam(required=false)String city){return city==null?bikes.findByAvailabilityAndVerificationStatus(Enums.AvailabilityStatus.AVAILABLE,Enums.VerificationStatus.VERIFIED):bikes.findByCityContainingIgnoreCaseAndAvailabilityAndVerificationStatus(city,Enums.AvailabilityStatus.AVAILABLE,Enums.VerificationStatus.VERIFIED);}
 @GetMapping("/{id}") public Bike one(@PathVariable Long id){return bikes.findById(id).orElseThrow();}
 @PostMapping public ResponseEntity<Bike> create(@Valid @RequestBody BikeRequest r){User u=users.findByEmail(SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow();Bike b=new Bike();b.setOwner(u);b.setName(r.name());b.setBrand(r.brand());b.setModel(r.model());b.setRegistrationNumber(r.registrationNumber());b.setDescription(r.description());b.setCity(r.city());b.setPickupLocation(r.pickupLocation());b.setType(r.type()==null?Enums.BikeType.OTHER:r.type());b.setFuelType(r.fuelType()==null?Enums.FuelType.NONE:r.fuelType());b.setPricePerHour(r.pricePerHour());b.setPricePerDay(r.pricePerDay());b.setDepositAmount(r.depositAmount()==null?BigDecimal.ZERO:r.depositAmount());b.setImageUrl(r.imageUrl());return ResponseEntity.status(201).body(bikes.save(b));}
}
